def count_valid_grids(H, W, S):
    # Count the number of '?' characters in the grid
    q = sum(row.count('?') for row in S)

    # If there are no '?' characters, the grid is already valid
    if q == 0:
        return 1

    # Initialize DP table
    dp = [[[[[0] * 4 for _ in range(4)] for _ in range(4)] for _ in range(W + 1)] for _ in range(H + 1)]
    dp[0][0][0][0][0] = 1

    # Fill the DP table
    for i in range(H):
