import sys

def can_transform(S, T):
    if len(S) == len(T):
        return sum(1 for s, t in zip(S, T) if s != t) <= 1
    elif len(S) + 1 == len(T):
        return any(can_transform(S[:i] + S[i+1:], T) for i in range(len(S)))
    elif len(S) - 1 == len(T):
