import sys
from collections import defaultdict

MOD = 998244353

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % MOD
    return result

def inverse_factorial(n):
    return pow(factorial(n), MOD - 2, MOD)

def count_sequences(N, A, B):
    # Count occurrences of each number in A and B
    count_A = [0] * (2 * N + 1)
    count_B = [0] * (2 * N + 1)

    for num in A:
        count_A[num] += 1

    for num in B:
        if num != -1:
            count_B[num] += 1

    # Check if any number appears more than once in A or B
    for i in range(1, 2 * N + 1):
        if count_A[i] > 1 or count_B[i] > 1:
            return 0

    # Calculate the number of valid permutations
    total_permutations = factorial(2 * N)

    # Adjust for the fixed positions in A and B
    for i in range(N):
        if B[i] != -1:
            total_permutations //= factorial(count_B[B[i]])

    return total_permutations % MOD

