class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        pq = [(moveTime[0][0], 0, 0)]
        visited = set()

        while pq:
            current_time, x, y = heappop(pq)
            if (x, y) in visited:
                continue
            visited.add((x, y))

            if x == n - 1 and y == m - 1:
                return max(current_time, moveTime[x][y])

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m:
                    next_time = max(current_time, moveTime[nx][ny]) + 1
                    heappush(pq, (next_time, nx, ny))

        return -1
