        n = len(nums)
        result = 0

        for start in range(n):
            if nums[start] != 0:
                continue

            direction = 1  # 1 for right, -1 for left
            curr = start
            visited = set()

            while True:
                if curr in visited:
                    break
                visited.add(curr)

                if nums[curr] == 0:
                    if len(visited) == n:
                        result += 1
                    break

                if nums[curr] > 0:
                    nums[curr] -= 1
                    direction *= -1

                curr += direction

