from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        # Create adjacency lists for both sets of currency pairs
        graph1 = {}
        for i in range(len(pairs1)):
            start, target = pairs1[i]
            rate = rates1[i]
            if start not in graph1:
                graph1[start] = []
            if target not in graph1:
                graph1[target] = []
            graph1[start].append((target, rate))
            graph1[target].append((start, 1 / rate))

        graph2 = {}
        for i in range(len(pairs2)):
            start, target = pairs2[i]
            rate = rates2[i]
            if start not in graph2:
                graph2[start] = []
            if target not in graph2:
                graph2[target] = []
            graph2[start].append((target, rate))
            graph2[target].append((start, 1 / rate))

        # Function to find the maximum amount using Dijkstra's algorithm
        def dijkstra(graph, start):
            distances = {currency: float('-inf') for currency in graph}
            distances[start] = 1.0
            pq = [(1.0, start)]

            while pq:
                current_rate, current_currency = heapq.heappop(pq)

                if current_rate < distances[current_currency]:
                    continue

                for neighbor, rate in graph[current_currency]:
                    new_rate = current_rate * rate
                    if new_rate > distances[neighbor]:
                        distances[neighbor] = new_rate
                        heapq.heappush(pq, (new_rate, neighbor))

            return distances

        # Find the maximum amount after day 1
        max_amount_day1 = dijkstra(graph1, initialCurrency)

        # Find the maximum amount after day 2
        max_amount_day2 = dijkstra(graph2, initialCurrency)

        # Combine the results from both days
        result = 0.0
        for currency, rate in max_amount_day1.items():
            if currency in max_amount_day2:
                result = max(result, rate * max_amount_day2[currency])

        return result
