class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        if k >= n - 1 or k == 0:
            return pow(m, n, MOD)

        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[1][0] = m

        for length in range(2, n + 1):
            prefix_sum = [0] * (k + 1)
            for prev_k in range(k, -1, -1):
                prefix_sum[prev_k] = (prefix_sum[prev_k] + dp[length - 1][prev_k]) % MOD
                if prev_k > 0:
                    dp[length][prev_k] = (dp[length][prev_k] + (m - 1) * prefix_sum[prev_k - 1]) % MOD

        return dp[n][k]
