def factorize(n):
    factors = []
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

def get_good_sequences(A):
    N = len(A) + 1
    dp = [[[] for _ in range(N)] for _ in range(N)]
    dp[0][0] = [(1, 1)]

    for i in range(N - 1):
        for j in range(N):
            for p, q in dp[i][j]:
                for k in range(1, A[i] + 1):
                    if (p * k) % q == 0:
                        new_p = p * k // q
                        new_q = q
                        if gcd(new_p, new_q) == 1:
                            dp[i + 1][j].append((new_p, new_q))
                    if (q * k) % p == 0:
                        new_p = p
                        new_q = q * k // p
                        if gcd(new_p, new_q) == 1:
                            dp[i + 1][j].append((new_p, new_q))

    good_sequences = []
    for j in range(N):
        for p, q in dp[N - 1][j]:
            if gcd(p, q) == 1:
                good_sequences.append((p, q))

    return good_sequences

