import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build the graph
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))

        # Helper function to check if we can reach all nodes with max weight <= mid
        def can_reach_all(mid):
            pq = [(-mid, 0)]  # Use negative weight for max-heap behavior
            visited = set()
            while pq:
                _, u = heapq.heappop(pq)
                if u in visited:
                    continue
                visited.add(u)
                if len(visited) == n:
                    return True
                for v, w in graph[u]:
                    if w <= mid and v not in visited:
                        heapq.heappush(pq, (-w, v))
            return False

        # Binary search for the minimum possible maximum edge weight
        left, right = 1, 10**6
        while left < right:
            mid = (left + right) // 2
            if can_reach_all(mid):
                right = mid
            else:
                left = mid + 1

        # Check if the final answer is valid
        if not can_reach_all(left):
            return -1
        return left
