    def countPartitions(self, nums: List[int]) -> int:
        total_sum = sum(nums)
        target = total_sum // 2
        dp = [False] * (target + 1)
        dp[0] = True
        for num in nums:
            for j in range(target, num - 1, -1):
                dp[j] |= dp[j - num]

        count = 0
        for i in range(target + 1):
            if dp[i]:
                count += 1

        return count * (count - 1) // 2
