class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        max_dist = 0

        for i in range(n):
            # Calculate the current position if we don't change anything
            x, y = 0, 0
            for j in range(i, n):
                if s[j] == 'N':
                    y += 1
                elif s[j] == 'S':
                    y -= 1
                elif s[j] == 'E':
                    x += 1
                else:
                    x -= 1

            # Calculate the number of changes needed to maximize the distance
            changes_needed = abs(x) + abs(y) - min(abs(x), abs(y))

            # If we have enough changes left, calculate the new maximum distance
            if changes_needed <= k:
                max_dist = max(max_dist, abs(x) + abs(y) + k - changes_needed)

        return max_dist
