        # Sort the bottom-left triangle (including the middle diagonal)
        for d in range(n):
            diag = []
            for i in range(d, n):
                diag.append(grid[i][d - i])
            diag.sort(reverse=True)
            for i in range(d, n):
                grid[i][d - i] = diag[i - d]

        # Sort the top-right triangle
        for d in range(1, n):
            diag = []
            for i in range(d, n):
                diag.append(grid[d - i][i])
            diag.sort()
            for i in range(d, n):
                grid[d - i][i] = diag[i - d + 1]

        return grid
