class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

        def is_valid(x, y):
            return 0 <= x < n and 0 <= y < m

        def get_next_direction(dx, dy):
            if dx == -1 and dy == -1:
                return (-1, 1)
            elif dx == -1 and dy == 1:
                return (1, 1)
            elif dx == 1 and dy == -1:
                return (1, -1)
            elif dx == 1 and dy == 1:
                return (-1, -1)

        max_length = 0

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    length = 1
                    current_direction = None

                    for dx, dy in directions:
                        x, y = i + dx, j + dy
                        next_dx, next_dy = get_next_direction(dx, dy)

                        while is_valid(x, y) and grid[x][y] % 2 == 0:
                            length += 1
                            x += dx
                            y += dy

                        if is_valid(x, y) and grid[x][y] == 1:
                            length += 1
                            x += next_dx
                            y += next_dy
                            current_direction = (next_dx, next_dy)

                        if current_direction:
                            break

                    max_length = max(max_length, length)

        return max_length
