class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        # Every single character is a palindrome of length 1
        for i in range(n):
            dp[i][i] = 1

        # Fill the table
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        # Check how many replacements are needed to make the entire string a palindrome
        replacements_needed = n - dp[0][-1]

        # If the number of replacements needed is less than or equal to k, return the length of the entire string
        if replacements_needed <= k:
            return n

        # Otherwise, find the longest palindromic subsequence that can be obtained by making at most k replacements
        for length in range(n, 0, -1):
            for i in range(n - length + 1):
                j = i + length - 1
                if abs(ord(s[i]) - ord(s[j])) <= k:
                    return length

        return 0
