class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        max_length = 0
        min_nodes = float('inf')

        def dfs(node, parent):
            nonlocal max_length, min_nodes
            first_max = second_max = 0

            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    length, nodes = dfs(neighbor, node)
                    if nums[neighbor] != nums[node]:
                        if length > first_max:
                            second_max = first_max
                            first_max = length
                        elif length > second_max:
                            second_max = length

                        total_length = first_max + second_max + weight
                        if total_length > max_length:
                            max_length = total_length
                            min_nodes = nodes
                        elif total_length == max_length:
                            min_nodes = min(min_nodes, nodes)

            return first_max + weight, 1

        dfs(0, -1)
        return [max_length, min_nodes]
