class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        result = []
        i = 0

        while i < n:
            char = caption[i]
            count = 1

            # Count consecutive characters
            while i + 1 < n and caption[i + 1] == char:
                i += 1
                count += 1

            # If count is less than 3, try to make it at least 3
            if count < 3:
                # Try changing the current character to its previous or next character
                prev_char = chr(ord(char) - 1) if char != 'a' else 'z'
                next_char = chr(ord(char) + 1) if char != 'z' else 'a'

                # Check which change results in a smaller lexicographical order
                if ord(prev_char) < ord(next_char):
                    result.extend([prev_char] * 3)
                elif ord(prev_char) > ord(next_char):
                    result.extend([next_char] * 3)
                else:
                    # If both changes result in the same lexicographical order, choose the one that minimizes operations
                    if count == 1:
                        result.append(prev_char)
                    else:
                        result.extend([prev_char] * 2)
            else:
                # If count is already 3 or more, just add the character as is
                result.extend([char] * count)

            i += 1

        # Join the list into a string and check if it's a valid good caption
        final_caption = ''.join(result)
        for i in range(1, len(final_caption)):
            if final_caption[i] != final_caption[i - 1]:
                return ""

        return final_caption
